  "696-1537bcb1": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<long long> a(n);\n    long long l = 0, r = 0;\n    for (auto &x : a) {\n        cin >> x;\n        l = max(l, x);\n        r += x;\n    }\n    auto ok = [&](long long c) {\n        int grupos = 1;\n        long long carga = 0;\n        for (auto x : a) {\n            if (carga + x > c) {\n                grupos++;\n                carga = 0;\n            }\n            carga += x;\n        }\n        return grupos <= k;\n    };\n    while (l < r) {\n        long long m = l + (r - l) / 2;\n        if (ok(m))\n            r = m;\n        else\n            l = m + 1;\n    }\n    cout << l << \"\\n\";\n}",
