  "874-69f14d09": "#include <iostream>\n#include <vector>\n#include <string>\n#include <queue>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<string> a(n);\n    for (auto &s : a)\n        cin >> s;\n    int ans = 0, dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n    for (int r = 0; r < n; r++)\n        for (int c = 0; c < m; c++)\n            if (a[r][c] == '.') {\n                ans++;\n                queue<pair<int, int>> q;\n                q.push({r, c});\n                a[r][c] = '#';\n                while (!q.empty()) {\n                    auto [x, y] = q.front();\n                    q.pop();\n                    for (int k = 0; k < 4; k++) {\n                        int u = x + dr[k], v = y + dc[k];\n                        if (u >= 0 && u < n && v >= 0 && v < m && a[u][v] == '.') {\n                            a[u][v] = '#';\n                            q.push({u, v});\n                        }\n                    }\n                }\n            }\n    cout << ans << \"\\n\";\n}",
