  "1247-669083b2": "#include <iostream>\n#include <vector>\n#include <queue>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> a(n, vector<int>(m));\n    int hi = 0;\n    for (auto &r : a)\n        for (int &x : r) {\n            cin >> x;\n            hi = max(hi, x);\n        }\n    int lo = max(a[0][0], a[n - 1][m - 1]);\n    auto ok = [&](int h) {\n        vector<vector<bool>> seen(n, vector<bool>(m));\n        queue<pair<int, int>> q;\n        q.push({0, 0});\n        seen[0][0] = true;\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        while (!q.empty()) {\n            auto [r, c] = q.front();\n            q.pop();\n            if (r == n - 1 && c == m - 1)\n                return true;\n            for (int z = 0; z < 4; z++) {\n                int x = r + dr[z], y = c + dc[z];\n                if (x >= 0 && x < n && y >= 0 && y < m && !seen[x][y] && a[x][y] <= h) {\n                    seen[x][y] = true;\n                    q.push({x, y});\n                }\n            }\n        }\n        return false;\n    };\n    while (lo < hi) {\n        int mid = lo + (hi - lo) / 2;\n        if (ok(mid))\n            hi = mid;\n        else\n            lo = mid + 1;\n    }\n    cout << lo << \"\\n\";\n}",
