  "656-481b5740": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<long long>> c(n, vector<long long>(n));\n    for (auto &r : c)\n        for (auto &x : r)\n            cin >> x;\n    int z = 1 << n;\n    const long long INF = 4000000000000000000LL;\n    vector<long long> d(z, INF);\n    d[0] = 0;\n    for (int mask = 0; mask < z; mask++) {\n        int k = 0;\n        for (int bits = mask; bits; bits &= bits - 1)\n            k++;\n        if (k == n)\n            continue;\n        for (int j = 0; j < n; j++)\n            if (!(mask & (1 << j)))\n                d[mask | (1 << j)] = min(d[mask | (1 << j)], d[mask] + c[k][j]);\n    }\n    cout << d[z - 1] << \"\\n\";\n}",
  "604-4d531899": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> p(n + 1);\n    for (int i = 0; i < n; i++) {\n        long long x;\n        cin >> x;\n        p[i + 1] = p[i] + x;\n    }\n    vector<vector<long long>> d(n, vector<long long>(n));\n    for (int len = 2; len <= n; len++)\n        for (int l = 0; l + len <= n; l++) {\n            int r = l + len - 1;\n            d[l][r] = 4000000000000000000LL;\n            for (int k = l; k < r; k++)\n                d[l][r] = min(d[l][r], d[l][k] + d[k + 1][r] + p[r + 1] - p[l]);\n        }\n    cout << d[0][n - 1] << \"\\n\";\n}",
