  "401-26d2a7b6": "#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> g(n);\n    while (m--) {\n        int a, b;\n        cin >> a >> b;\n        g[a].push_back(b);\n        g[b].push_back(a);\n    }\n    vector<int> d(n, -1);\n    queue<int> q;\n    d[0] = 0;\n    q.push(0);\n    while (!q.empty()) {\n        int v = q.front();\n        q.pop();\n        for (int u : g[v])\n            if (d[u] == -1) {\n                d[u] = d[v] + 1;\n                q.push(u);\n            }\n    }\n    for (int x : d)\n        cout << x << \" \";\n    cout << \"\\n\";\n}",
