  "169-42127a4b": "bool join(int a, int b) {\n    a = find(a);\n    b = find(b);\n    if (a == b)\n        return false;\n    if (s[a] < s[b])\n        swap(a, b);\n    p[b] = a;\n    s[a] += s[b];\n    return true;\n}",
  "667-8f1e0491": "#include <iostream>\n#include <vector>\n#include <numeric>\n#include <algorithm>\nusing namespace std;\nstruct DSU {\n    vector<int> p, s;\n    DSU(int n) : p(n), s(n, 1) {\n        iota(p.begin(), p.end(), 0);\n    }\n    int find(int x) {\n        return p[x] == x ? x : p[x] = find(p[x]);\n    }\n    bool join(int a, int b) {\n        a = find(a);\n        b = find(b);\n        if (a == b)\n            return false;\n        if (s[a] < s[b])\n            swap(a, b);\n        p[b] = a;\n        s[a] += s[b];\n        return true;\n    }\n};\nint main() {\n    int n, m;\n    cin >> n >> m;\n    DSU d(n);\n    int components = n;\n    while (m--) {\n        int a, b;\n        cin >> a >> b;\n        components -= d.join(a, b);\n    }\n    cout << components << \"\\n\";\n}",
  "484-78482a6d": "#include <iostream>\n#include <vector>\n#include <numeric>\n#include <algorithm>\nusing namespace std;\nstruct DSU {\n    vector<int> p, s;\n    DSU(int n) : p(n), s(n, 1) {\n        iota(p.begin(), p.end(), 0);\n    }\n    int find(int x) {\n        return p[x] == x ? x : p[x] = find(p[x]);\n    }\n    bool join(int a, int b) {\n        a = find(a);\n        b = find(b);\n        if (a == b)\n            return false;\n        if (s[a] < s[b])\n            swap(a, b);\n        p[b] = a;\n        s[a] += s[b];\n        return true;\n    }\n};\nint main() {\n    int n, m;\n    cin >> n >> m;\n    DSU d(n);\n    int components = n;\n    while (m--) {\n        int a, b;\n        cin >> a >> b;\n        components -= d.join(a, b);\n    }\n    cout << components << \"\\n\";\n}",
