  "609-d1897f03": "#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> g(n);\n    vector<int> in(n), order;\n    while (m--) {\n        int a, b;\n        cin >> a >> b;\n        g[a].push_back(b);\n        in[b]++;\n    }\n    queue<int> q;\n    for (int i = 0; i < n; i++)\n        if (!in[i])\n            q.push(i);\n    while (!q.empty()) {\n        int v = q.front();\n        q.pop();\n        order.push_back(v);\n        for (int u : g[v])\n            if (--in[u] == 0)\n                q.push(u);\n    }\n    if ((int)order.size() != n)\n        cout << \"CICLO\\n\";\n    else {\n        for (int v : order)\n            cout << v << \" \";\n        cout << \"\\n\";\n    }\n}",
