  "749-d0adb9b8": "#include <iostream>\n#include <vector>\n#include <queue>\n#include <functional>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    using P = pair<long long, int>;\n    vector<vector<P>> g(n);\n    while (m--) {\n        int a, b;\n        long long w;\n        cin >> a >> b >> w;\n        g[a].push_back({w, b});\n    }\n    const long long INF = 4000000000000000000LL;\n    vector<long long> d(n, INF);\n    priority_queue<P, vector<P>, greater<P>> q;\n    d[0] = 0;\n    q.push({0, 0});\n    while (!q.empty()) {\n        auto [x, v] = q.top();\n        q.pop();\n        if (x != d[v])\n            continue;\n        for (auto [w, u] : g[v])\n            if (w <= INF - x && x + w < d[u]) {\n                d[u] = x + w;\n                q.push({d[u], u});\n            }\n    }\n    for (auto x : d)\n        cout << (x == INF ? -1 : x) << \" \";\n    cout << \"\\n\";\n}",
  "561-9bb96c6a": "#include <iostream>\n#include <vector>\n#include <queue>\n#include <functional>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    using P = pair<long long, int>;\n    vector<vector<P>> g(n);\n    while (m--) {\n        int a, b;\n        long long w;\n        cin >> a >> b >> w;\n        g[a].push_back({w, b});\n    }\n    const long long INF = 4000000000000000000LL;\n    vector<long long> d(n, INF);\n    priority_queue<P, vector<P>, greater<P>> q;\n    d[0] = 0;\n    q.push({0, 0});\n    while (!q.empty()) {\n        auto [x, v] = q.top();\n        q.pop();\n        if (x != d[v])\n            continue;\n        for (auto [w, u] : g[v])\n            if (w <= INF - x && x + w < d[u]) {\n                d[u] = x + w;\n                q.push({d[u], u});\n            }\n    }\n    for (auto x : d)\n        cout << (x == INF ? -1 : x) << \" \";\n    cout << \"\\n\";\n}",
  "970-48bf4ce9": "#include <iostream>\n#include <vector>\n#include <tuple>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nstruct DSU {\n    vector<int> p, s;\n    DSU(int n) : p(n), s(n, 1) {\n        iota(p.begin(), p.end(), 0);\n    }\n    int f(int x) {\n        return p[x] == x ? x : p[x] = f(p[x]);\n    }\n    bool join(int a, int b) {\n        a = f(a);\n        b = f(b);\n        if (a == b)\n            return false;\n        if (s[a] < s[b])\n            swap(a, b);\n        p[b] = a;\n        s[a] += s[b];\n        return true;\n    }\n};\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<tuple<long long, int, int>> e;\n    while (m--) {\n        int a, b;\n        long long w;\n        cin >> a >> b >> w;\n        e.push_back({w, a, b});\n    }\n    sort(e.begin(), e.end());\n    DSU d(n);\n    long long ans = 0;\n    int used = 0;\n    for (auto [w, a, b] : e)\n        if (d.join(a, b)) {\n            ans += w;\n            used++;\n        }\n    if (used == n - 1)\n        cout << ans << \"\\n\";\n    else\n        cout << \"IMPOSIBLE\\n\";\n}",
  "1004-6cffe653": "#include <iostream>\n#include <vector>\n#include <tuple>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nstruct DSU {\n    vector<int> p, s;\n    DSU(int n) : p(n), s(n, 1) {\n        iota(p.begin(), p.end(), 0);\n    }\n    int f(int x) {\n        return p[x] == x ? x : p[x] = f(p[x]);\n    }\n    bool join(int a, int b) {\n        a = f(a);\n        b = f(b);\n        if (a == b)\n            return false;\n        if (s[a] < s[b])\n            swap(a, b);\n        p[b] = a;\n        s[a] += s[b];\n        return true;\n    }\n};\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<tuple<long long, int, int>> e;\n    while (m--) {\n        int a, b;\n        long long w;\n        cin >> a >> b >> w;\n        e.push_back({w, a, b});\n    }\n    sort(e.begin(), e.end());\n    DSU d(n);\n    long long ans = 0;\n    int used = 0;\n    for (auto [w, a, b] : e)\n        if (d.join(a, b)) {\n            ans += w;\n            used++;\n        }\n    if (used == n - 1)\n        cout << ans << \"\\n\";\n    else\n        cout << \"IMPOSIBLE\\n\";\n}",
  "464-7a0e2b1b": "#include <iostream>\n#include <set>\nusing namespace std;\nint main() {\n    int n, q;\n    cin >> n >> q;\n    multiset<long long> s;\n    while (n--) {\n        long long x;\n        cin >> x;\n        s.insert(x);\n    }\n    while (q--) {\n        long long x;\n        cin >> x;\n        auto it = s.upper_bound(x);\n        if (it == s.begin())\n            cout << -1 << \"\\n\";\n        else {\n            --it;\n            cout << *it << \"\\n\";\n            s.erase(it);\n        }\n    }\n}",
