  "438-b9793a64": "#include <iostream>\n#include <vector>\n#include <deque>\nusing namespace std;\nint main() {\n    int n, k;\n    cin >> n >> k;\n    if (k < 1 || k > n)\n        return 0;\n    vector<long long> a(n);\n    deque<int> q;\n    for (int i = 0; i < n; i++) {\n        cin >> a[i];\n        while (!q.empty() && q.front() <= i - k)\n            q.pop_front();\n        while (!q.empty() && a[q.back()] <= a[i])\n            q.pop_back();\n        q.push_back(i);\n        if (i >= k - 1)\n            cout << a[q.front()] << \" \";\n    }\n    cout << \"\\n\";\n}",
