  "310-c4993420": "void agregar(int v, int l, int r, int posicion, long long x) {\n    if (l == r) {\n        arbol[v] += x;\n        return;\n    }\n    int m = (l + r) / 2;\n    if (posicion <= m)\n        agregar(2 * v, l, m, posicion, x);\n    else\n        agregar(2 * v + 1, m + 1, r, posicion, x);\n    arbol[v] = arbol[2 * v] + arbol[2 * v + 1];\n}",
  "1356-808b60eb": "#include <iostream>\n#include <vector>\nusing namespace std;\nvector<long long> a, arbol;\n\nvoid construir(int v, int l, int r) {\n    if (l == r) {\n        arbol[v] = a[l];\n        return;\n    }\n    int m = (l + r) / 2;\n    construir(2 * v, l, m);\n    construir(2 * v + 1, m + 1, r);\n    arbol[v] = arbol[2 * v] + arbol[2 * v + 1];\n}\n\nlong long consultar(int v, int l, int r, int desde, int hasta) {\n    if (r < desde || hasta < l)\n        return 0;\n    if (desde <= l && r <= hasta)\n        return arbol[v];\n    int m = (l + r) / 2;\n    return consultar(2 * v, l, m, desde, hasta) +\n           consultar(2 * v + 1, m + 1, r, desde, hasta);\n}\n\nvoid agregar(int v, int l, int r, int posicion, long long x) {\n    if (l == r) {\n        arbol[v] += x;\n        return;\n    }\n    int m = (l + r) / 2;\n    if (posicion <= m)\n        agregar(2 * v, l, m, posicion, x);\n    else\n        agregar(2 * v + 1, m + 1, r, posicion, x);\n    arbol[v] = arbol[2 * v] + arbol[2 * v + 1];\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, q;\n    cin >> n >> q;\n    a.resize(n + 1);\n    arbol.resize(4 * n);\n    for (int i = 1; i <= n; i++)\n        cin >> a[i];\n    construir(1, 1, n);\n    while (q--) {\n        int tipo, l;\n        long long r;\n        cin >> tipo >> l >> r;\n        if (tipo == 1)\n            agregar(1, 1, n, l, r);\n        else\n            cout << consultar(1, 1, n, l, (int)r) << '\\n';\n    }\n}",
