  "574-b1d06147": "#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    int n, q;\n    cin >> n >> q;\n    vector<long long> b(n + 1);\n    auto add = [&](int i, long long x) {\n        for (; i <= n; i += i & -i)\n            b[i] += x;\n    };\n    auto sum = [&](int i) {\n        long long s = 0;\n        for (; i > 0; i -= i & -i)\n            s += b[i];\n        return s;\n    };\n    for (int i = 1; i <= n; i++) {\n        long long x;\n        cin >> x;\n        add(i, x);\n    }\n    while (q--) {\n        int t, l;\n        long long r;\n        cin >> t >> l >> r;\n        if (t == 1)\n            add(l, r);\n        else\n            cout << sum((int)r) - sum(l - 1) << \"\\n\";\n    }\n}",
  "394-e2fca5e3": "#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    int n, q;\n    cin >> n >> q;\n    vector<long long> b(n + 1);\n    auto add = [&](int i, long long x) {\n        for (; i <= n; i += i & -i)\n            b[i] += x;\n    };\n    auto sum = [&](int i) {\n        long long s = 0;\n        for (; i > 0; i -= i & -i)\n            s += b[i];\n        return s;\n    };\n    for (int i = 1; i <= n; i++) {\n        long long x;\n        cin >> x;\n        add(i, x);\n    }\n    while (q--) {\n        int t, l;\n        long long r;\n        cin >> t >> l >> r;\n        if (t == 1)\n            add(l, r);\n        else\n            cout << sum((int)r) - sum(l - 1) << \"\\n\";\n    }\n}",
  "789-5dfdf4ff": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> take(n), skip(n);\n    for (auto &x : take)\n        cin >> x;\n    vector<vector<int>> g(n);\n    for (int i = 1; i < n; i++) {\n        int a, b;\n        cin >> a >> b;\n        --a;\n        --b;\n        g[a].push_back(b);\n        g[b].push_back(a);\n    }\n    vector<int> p(n, -1), o{0};\n    for (int i = 0; i < n; i++) {\n        int v = o[i];\n        for (int u : g[v])\n            if (u != p[v]) {\n                p[u] = v;\n                o.push_back(u);\n            }\n    }\n    for (int i = n - 1; i > 0; i--) {\n        int v = o[i];\n        take[p[v]] += skip[v];\n        skip[p[v]] += max(take[v], skip[v]);\n    }\n    cout << max(take[0], skip[0]) << \"\\n\";\n}",
