  "962-d1d664f8": "#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    int n, q;\n    cin >> n >> q;\n    vector<long long> a(n);\n    for (auto &x : a)\n        cin >> x;\n    vector<vector<int>> g(n);\n    for (int i = 1; i < n; i++) {\n        int u, v;\n        cin >> u >> v;\n        --u;\n        --v;\n        g[u].push_back(v);\n        g[v].push_back(u);\n    }\n    vector<int> p(n, -1), tin(n), sz(n, 1), st{0}, o;\n    while (!st.empty()) {\n        int v = st.back();\n        st.pop_back();\n        tin[v] = o.size();\n        o.push_back(v);\n        for (int u : g[v])\n            if (u != p[v]) {\n                p[u] = v;\n                st.push_back(u);\n            }\n    }\n    for (int i = n - 1; i > 0; i--)\n        sz[p[o[i]]] += sz[o[i]];\n    vector<long long> pref(n + 1);\n    for (int i = 0; i < n; i++)\n        pref[i + 1] = pref[i] + a[o[i]];\n    while (q--) {\n        int v;\n        cin >> v;\n        --v;\n        cout << pref[tin[v] + sz[v]] - pref[tin[v]] << \"\\n\";\n    }\n}",
