  "1662-948388cc": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n, q;\n    cin >> n >> q;\n    vector<vector<int>> g(n);\n    for (int i = 1; i < n; i++) {\n        int a, b;\n        cin >> a >> b;\n        --a;\n        --b;\n        g[a].push_back(b);\n        g[b].push_back(a);\n    }\n    vector<int> p(n, -1), dep(n), first(n, -1), next(n), st{0}, e;\n    first[0] = 0;\n    e.push_back(0);\n    while (!st.empty()) {\n        int v = st.back();\n        if (next[v] == (int)g[v].size()) {\n            st.pop_back();\n            if (!st.empty())\n                e.push_back(st.back());\n        } else {\n            int u = g[v][next[v]++];\n            if (u == p[v])\n                continue;\n            p[u] = v;\n            dep[u] = dep[v] + 1;\n            first[u] = e.size();\n            e.push_back(u);\n            st.push_back(u);\n        }\n    }\n    auto best = [&](int a, int b) {\n        if (a == -1)\n            return b;\n        if (b == -1)\n            return a;\n        return dep[a] < dep[b] ? a : b;\n    };\n    int z = 1;\n    while (z < (int)e.size())\n        z *= 2;\n    vector<int> seg(2 * z, -1);\n    for (int i = 0; i < (int)e.size(); i++)\n        seg[z + i] = e[i];\n    for (int i = z - 1; i; i--)\n        seg[i] = best(seg[2 * i], seg[2 * i + 1]);\n    while (q--) {\n        int a, b;\n        cin >> a >> b;\n        int l = first[a - 1], r = first[b - 1];\n        if (l > r)\n            swap(l, r);\n        l += z;\n        r += z + 1;\n        int ans = -1;\n        while (l < r) {\n            if (l & 1)\n                ans = best(ans, seg[l++]);\n            if (r & 1)\n                ans = best(ans, seg[--r]);\n            l /= 2;\n            r /= 2;\n        }\n        cout << ans + 1 << \"\\n\";\n    }\n}",
