  "979-fe38f3e": "#include <iostream>\n#include <vector>\nusing namespace std;\nstruct BIT {\n    int n;\n    vector<long long> t;\n    BIT(int n) : n(n), t(n + 1) {\n    }\n    void add(int p, long long x) {\n        for (; p <= n; p += p & -p)\n            t[p] += x;\n    }\n    long long sum(int p) {\n        long long z = 0;\n        for (; p; p -= p & -p)\n            z += t[p];\n        return z;\n    }\n};\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, q;\n    cin >> n >> q;\n    BIT b(n), c(n);\n    auto change = [&](int p, long long x) {\n        if (p <= n) {\n            b.add(p, x);\n            c.add(p, x * (p - 1));\n        }\n    };\n    auto pref = [&](int p) { return p * b.sum(p) - c.sum(p); };\n    while (q--) {\n        int type, l, r;\n        cin >> type >> l >> r;\n        if (type == 1) {\n            long long x;\n            cin >> x;\n            change(l, x);\n            change(r + 1, -x);\n        } else\n            cout << pref(r) - pref(l - 1) << '\\n';\n    }\n}",
  "275-d46ed786": "void aplicar(int v, int L, int R, long long x) {\n    suma[v] += x * (R - L + 1);\n    lazy[v] += x;\n}\nvoid repartir(int v, int L, int R) {\n    if (L == R)\n        return;\n    int M = (L + R) / 2;\n    aplicar(2 * v, L, M, lazy[v]);\n    aplicar(2 * v + 1, M + 1, R, lazy[v]);\n    lazy[v] = 0;\n}",
