  "1312-4b4aa4ec": "#include <iostream>\n#include <vector>\nusing namespace std;\nstruct Node {\n    int a = -1, b = -1;\n    long long sum = 0;\n};\nvector<Node> t;\nlong long value(int v) {\n    return v < 0 ? 0 : t[v].sum;\n}\nint add(int v, long long L, long long R, long long x, long long d) {\n    if (v < 0) {\n        v = t.size();\n        t.push_back({});\n    }\n    if (R - L == 1) {\n        t[v].sum += d;\n        return v;\n    }\n    long long M = L + (R - L) / 2;\n    if (x < M) {\n        int child = add(t[v].a, L, M, x, d);\n        t[v].a = child;\n    } else {\n        int child = add(t[v].b, M, R, x, d);\n        t[v].b = child;\n    }\n    t[v].sum = value(t[v].a) + value(t[v].b);\n    return v;\n}\nlong long query(int v, long long L, long long R, long long l, long long r) {\n    if (v < 0 || R <= l || r <= L)\n        return 0;\n    if (l <= L && R <= r)\n        return t[v].sum;\n    long long M = L + (R - L) / 2;\n    return query(t[v].a, L, M, l, r) + query(t[v].b, M, R, l, r);\n}\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    long long U;\n    int q;\n    cin >> U >> q;\n    int root = -1;\n    while (q--) {\n        int k;\n        long long x, y;\n        cin >> k >> x >> y;\n        if (k == 1)\n            root = add(root, 0, U, x, y);\n        else\n            cout << query(root, 0, U, x, y) << '\\n';\n    }\n}",
