  "1324-b7c5d063": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nconst long long MOD = 1000000007;\nstruct F {\n    long long a, b;\n};\nF join(F f, F g) {\n    return {g.a * f.a % MOD, (g.a * f.b + g.b) % MOD};\n}\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, q;\n    cin >> n >> q;\n    vector<F> a(n);\n    for (auto &f : a)\n        cin >> f.a >> f.b;\n    int K = 1;\n    while ((1 << K) < n)\n        K++;\n    vector<vector<F>> t(K, vector<F>(n));\n    for (int k = 0; k < K; k++) {\n        int half = 1 << k;\n        for (int L = 0; L < n; L += 2 * half) {\n            int M = min(n, L + half), R = min(n, L + 2 * half);\n            t[k][M - 1] = a[M - 1];\n            for (int i = M - 2; i >= L; i--)\n                t[k][i] = join(a[i], t[k][i + 1]);\n            if (M < R) {\n                t[k][M] = a[M];\n                for (int i = M + 1; i < R; i++)\n                    t[k][i] = join(t[k][i - 1], a[i]);\n            }\n        }\n    }\n    while (q--) {\n        int l, r;\n        long long x;\n        cin >> l >> r >> x;\n        --l;\n        --r;\n        F f;\n        if (l == r)\n            f = a[l];\n        else {\n            int k = 31 - __builtin_clz((unsigned)(l ^ r));\n            f = join(t[k][l], t[k][r]);\n        }\n        cout << (f.a * x + f.b) % MOD << '\\n';\n    }\n}",
