  "992-cb3f3e04": "#include <iostream>\n#include <algorithm>\nusing namespace std;\nstruct P {\n    long long x, y;\n};\nlong long cross(P a, P b, P c) {\n    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);\n}\nint sign(long long x) {\n    return (x > 0) - (x < 0);\n}\nbool on(P a, P b, P p) {\n    return cross(a, b, p) == 0 && min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) &&\n           min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y);\n}\nbool hit(P a, P b, P c, P d) {\n    auto x = cross(a, b, c), y = cross(a, b, d), z = cross(c, d, a), w = cross(c, d, b);\n    if (sign(x) * sign(y) < 0 && sign(z) * sign(w) < 0)\n        return true;\n    return (!x && on(a, b, c)) || (!y && on(a, b, d)) || (!z && on(c, d, a)) ||\n           (!w && on(c, d, b));\n}\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int q;\n    cin >> q;\n    while (q--) {\n        P a, b, c, d;\n        cin >> a.x >> a.y >> b.x >> b.y >> c.x >> c.y >> d.x >> d.y;\n        cout << (hit(a, b, c, d) ? \"SI\" : \"NO\") << '\\n';\n    }\n}",
  "603-db4c403f": "function<void(int, int, int, int, int, int)> update = [&](int v, int L, int R, int l,\n                                                          int r, int d) {\n    if (r < L || R < l)\n        return;\n    if (l <= L && R <= r)\n        cover[v] += d;\n    else {\n        int M = (L + R) / 2;\n        update(2 * v, L, M, l, r, d);\n        update(2 * v + 1, M + 1, R, l, r, d);\n    }\n    if (cover[v] > 0)\n        len[v] = ys[R + 1] - ys[L];\n    else if (L == R)\n        len[v] = 0;\n    else\n        len[v] = len[2 * v] + len[2 * v + 1];\n};",
