  "1813-2754597c": "#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <functional>\nusing namespace std;\nstruct E {\n    long long x, y, z;\n    int d;\n};\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<E> ev;\n    vector<long long> ys;\n    while (n--) {\n        long long x, y, X, Y;\n        cin >> x >> y >> X >> Y;\n        if (x == X || y == Y)\n            continue;\n        ev.push_back({x, y, Y, 1});\n        ev.push_back({X, y, Y, -1});\n        ys.push_back(y);\n        ys.push_back(Y);\n    }\n    if (ev.empty()) {\n        cout << 0 << '\\n';\n        return 0;\n    }\n    sort(ys.begin(), ys.end());\n    ys.erase(unique(ys.begin(), ys.end()), ys.end());\n    sort(ev.begin(), ev.end(), [](E a, E b) { return a.x < b.x; });\n    int m = ys.size() - 1;\n    vector<int> cover(4 * m);\n    vector<long long> len(4 * m);\n    function<void(int, int, int, int, int, int)> update = [&](int v, int L, int R,\n                                                              int l, int r, int d) {\n        if (r < L || R < l)\n            return;\n        if (l <= L && R <= r)\n            cover[v] += d;\n        else {\n            int M = (L + R) / 2;\n            update(2 * v, L, M, l, r, d);\n            update(2 * v + 1, M + 1, R, l, r, d);\n        }\n        if (cover[v] > 0)\n            len[v] = ys[R + 1] - ys[L];\n        else if (L == R)\n            len[v] = 0;\n        else\n            len[v] = len[2 * v] + len[2 * v + 1];\n    };\n    long long area = 0, prev = ev[0].x;\n    for (auto e : ev) {\n        area += len[1] * (e.x - prev);\n        prev = e.x;\n        int l = lower_bound(ys.begin(), ys.end(), e.y) - ys.begin(),\n            r = lower_bound(ys.begin(), ys.end(), e.z) - ys.begin() - 1;\n        update(1, 0, m - 1, l, r, e.d);\n    }\n    cout << area << '\\n';\n}",
