  "1369-5ef26c3b": "#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cstdlib>\nusing namespace std;\nstruct P {\n    long long x, y;\n    bool operator<(const P &o) const {\n        return x != o.x ? x < o.x : y < o.y;\n    }\n    bool operator==(const P &o) const {\n        return x == o.x && y == o.y;\n    }\n};\nlong long cross(P a, P b, P c) {\n    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);\n}\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<P> a(n);\n    for (auto &p : a)\n        cin >> p.x >> p.y;\n    sort(a.begin(), a.end());\n    a.erase(unique(a.begin(), a.end()), a.end());\n    n = a.size();\n    if (n < 3) {\n        cout << 0 << '\\n';\n        return 0;\n    }\n    vector<P> lo, hi;\n    for (P p : a) {\n        while (lo.size() >= 2 && cross(lo[lo.size() - 2], lo.back(), p) <= 0)\n            lo.pop_back();\n        lo.push_back(p);\n    }\n    for (int i = n - 1; i >= 0; i--) {\n        P p = a[i];\n        while (hi.size() >= 2 && cross(hi[hi.size() - 2], hi.back(), p) <= 0)\n            hi.pop_back();\n        hi.push_back(p);\n    }\n    lo.pop_back();\n    hi.pop_back();\n    lo.insert(lo.end(), hi.begin(), hi.end());\n    long long area = 0;\n    for (int i = 0; i < (int)lo.size(); i++) {\n        P p = lo[i], q = lo[(i + 1) % lo.size()];\n        area += p.x * q.y - p.y * q.x;\n    }\n    cout << llabs(area) << '\\n';\n}",
