  "615-e105e05": "function<void(int, int, int, int)> solve = [&](int L, int R, int optL, int optR) {\n    if (L > R)\n        return;\n    int M = (L + R) / 2, best = optL;\n    for (int j = optL; j <= min(optR, M - 1); j++)\n        if (prev[j] < INF) {\n            long long d = S[M] - S[j], v = prev[j] + d * d;\n            if (v < cur[M]) {\n                cur[M] = v;\n                best = j;\n            }\n        }\n    solve(L, M - 1, optL, best);\n    solve(M + 1, R, best, optR);\n};\nsolve(k, n, k - 1, n - 1);",
  "1224-c0aab7c6": "#include <iostream>\n#include <vector>\n#include <functional>\n#include <algorithm>\nusing namespace std;\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, K;\n    cin >> n >> K;\n    vector<long long> S(n + 1);\n    for (int i = 1; i <= n; i++) {\n        long long x;\n        cin >> x;\n        S[i] = S[i - 1] + x;\n    }\n    const long long INF = 4000000000000000000LL;\n    vector<long long> prev(n + 1, INF), cur(n + 1);\n    prev[0] = 0;\n    for (int k = 1; k <= K; k++) {\n        fill(cur.begin(), cur.end(), INF);\n        function<void(int, int, int, int)> solve = [&](int L, int R, int optL,\n                                                       int optR) {\n            if (L > R)\n                return;\n            int M = (L + R) / 2, best = optL;\n            for (int j = optL; j <= min(optR, M - 1); j++)\n                if (prev[j] < INF) {\n                    long long d = S[M] - S[j], v = prev[j] + d * d;\n                    if (v < cur[M]) {\n                        cur[M] = v;\n                        best = j;\n                    }\n                }\n            solve(L, M - 1, optL, best);\n            solve(M + 1, R, best, optR);\n        };\n        solve(k, n, k - 1, n - 1);\n        prev.swap(cur);\n    }\n    cout << prev[n] << '\\n';\n}",
