  "291-f2f64058": "while (q--) {\n    int k, l, r;\n    cin >> k >> l >> r;\n    auto [a, rest] = split(root, l - 1);\n    auto [b, c] = split(rest, r - l + 1);\n    if (k == 1)\n        flip(b);\n    else\n        cout << sum(b) << '\\n';\n    root = merge(a, merge(b, c));\n}",
  "1996-15d12dae": "#include <iostream>\n#include <vector>\n#include <cstdint>\n#include <algorithm>\nusing namespace std;\nstruct Node {\n    int l = 0, r = 0, size = 1;\n    long long value = 0, sum = 0;\n    uint32_t priority = 0;\n    bool rev = false;\n};\nvector<Node> t;\nint size(int v) {\n    return v ? t[v].size : 0;\n}\nlong long sum(int v) {\n    return v ? t[v].sum : 0;\n}\nvoid pull(int v) {\n    t[v].size = 1 + size(t[v].l) + size(t[v].r);\n    t[v].sum = t[v].value + sum(t[v].l) + sum(t[v].r);\n}\nvoid flip(int v) {\n    if (v) {\n        swap(t[v].l, t[v].r);\n        t[v].rev = !t[v].rev;\n    }\n}\nvoid push(int v) {\n    if (t[v].rev) {\n        flip(t[v].l);\n        flip(t[v].r);\n        t[v].rev = false;\n    }\n}\npair<int, int> split(int v, int k) {\n    if (!v)\n        return {0, 0};\n    push(v);\n    if (k <= size(t[v].l)) {\n        auto [a, b] = split(t[v].l, k);\n        t[v].l = b;\n        pull(v);\n        return {a, v};\n    }\n    auto [a, b] = split(t[v].r, k - size(t[v].l) - 1);\n    t[v].r = a;\n    pull(v);\n    return {v, b};\n}\nint merge(int a, int b) {\n    if (!a || !b)\n        return a ? a : b;\n    if (t[a].priority > t[b].priority) {\n        push(a);\n        t[a].r = merge(t[a].r, b);\n        pull(a);\n        return a;\n    }\n    push(b);\n    t[b].l = merge(a, t[b].l);\n    pull(b);\n    return b;\n}\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n, q;\n    cin >> n >> q;\n    t.resize(n + 1);\n    uint32_t seed = 2463534242u;\n    int root = 0;\n    for (int i = 1; i <= n; i++) {\n        cin >> t[i].value;\n        t[i].sum = t[i].value;\n        seed ^= seed << 13;\n        seed ^= seed >> 17;\n        seed ^= seed << 5;\n        t[i].priority = seed;\n        root = merge(root, i);\n    }\n    while (q--) {\n        int k, l, r;\n        cin >> k >> l >> r;\n        auto [a, rest] = split(root, l - 1);\n        auto [b, c] = split(rest, r - l + 1);\n        if (k == 1)\n            flip(b);\n        else\n            cout << sum(b) << '\\n';\n        root = merge(a, merge(b, c));\n    }\n}",
  "541-fb621d16": "function<void(int, int, int, Line)> insert = [&](int v, int l, int r, Line g) {\n    if (!has[v]) {\n        t[v] = g;\n        has[v] = true;\n        return;\n    }\n    int mid = (l + r) / 2;\n    bool left = g.at(xs[l]) < t[v].at(xs[l]), middle = g.at(xs[mid]) < t[v].at(xs[mid]);\n    if (middle)\n        swap(t[v], g);\n    if (l == r)\n        return;\n    if (left != middle)\n        insert(2 * v, l, mid, g);\n    else\n        insert(2 * v + 1, mid + 1, r, g);\n};",
  "577-80f27444": "long long ans = 4000000000000000000LL;\nint p = lower_bound(xs.begin(), xs.end(), o.a) - xs.begin(), v = 1, l = 0, r = n - 1;\nwhile (true) {\n    if (has[v])\n        ans = min(ans, t[v].at(o.a));\n    if (l == r)\n        break;\n    int mid = (l + r) / 2;\n    if (p <= mid) {\n        v *= 2;\n        r = mid;\n    } else {\n        v = v * 2 + 1;\n        l = mid + 1;\n    }\n}",
  "2146-6a87c340": "#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <functional>\nusing namespace std;\nstruct Line {\n    long long m = 0, b = 0;\n    long long at(long long x) const {\n        return m * x + b;\n    }\n};\nstruct Op {\n    int type;\n    long long a, b;\n};\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int q;\n    cin >> q;\n    vector<Op> ops;\n    vector<long long> xs;\n    while (q--) {\n        Op o;\n        cin >> o.type >> o.a;\n        o.b = 0;\n        if (o.type == 1)\n            cin >> o.b;\n        else\n            xs.push_back(o.a);\n        ops.push_back(o);\n    }\n    sort(xs.begin(), xs.end());\n    xs.erase(unique(xs.begin(), xs.end()), xs.end());\n    int n = xs.size();\n    vector<Line> t(4 * n);\n    vector<bool> has(4 * n);\n    function<void(int, int, int, Line)> insert = [&](int v, int l, int r, Line g) {\n        if (!has[v]) {\n            t[v] = g;\n            has[v] = true;\n            return;\n        }\n        int mid = (l + r) / 2;\n        bool left = g.at(xs[l]) < t[v].at(xs[l]),\n             middle = g.at(xs[mid]) < t[v].at(xs[mid]);\n        if (middle)\n            swap(t[v], g);\n        if (l == r)\n            return;\n        if (left != middle)\n            insert(2 * v, l, mid, g);\n        else\n            insert(2 * v + 1, mid + 1, r, g);\n    };\n    for (auto o : ops) {\n        if (o.type == 1)\n            insert(1, 0, n - 1, {o.a, o.b});\n        else {\n            long long ans = 4000000000000000000LL;\n            int p = lower_bound(xs.begin(), xs.end(), o.a) - xs.begin(), v = 1, l = 0,\n                r = n - 1;\n            while (true) {\n                if (has[v])\n                    ans = min(ans, t[v].at(o.a));\n                if (l == r)\n                    break;\n                int mid = (l + r) / 2;\n                if (p <= mid) {\n                    v *= 2;\n                    r = mid;\n                } else {\n                    v = v * 2 + 1;\n                    l = mid + 1;\n                }\n            }\n            if (ans == 4000000000000000000LL)\n                cout << \"NINGUNA\\n\";\n            else\n                cout << ans << '\\n';\n        }\n    }\n}",
