  "1272-26590b9b": "#include <iostream>\n#include <vector>\n#include <queue>\n#include <algorithm>\nusing namespace std;\nstruct Flow {\n    int n;\n    vector<vector<long long>> c;\n    Flow(int n) : n(n), c(n, vector<long long>(n)) {\n    }\n    void add(int a, int b, long long x) {\n        c[a][b] += x;\n    }\n    long long run(int s, int t) {\n        long long ans = 0;\n        while (true) {\n            vector<int> p(n, -1);\n            queue<int> q;\n            q.push(s);\n            p[s] = s;\n            while (!q.empty() && p[t] == -1) {\n                int v = q.front();\n                q.pop();\n                for (int u = 0; u < n; u++)\n                    if (p[u] == -1 && c[v][u] > 0) {\n                        p[u] = v;\n                        q.push(u);\n                    }\n            }\n            if (p[t] == -1)\n                break;\n            long long f = 4000000000000000000LL;\n            for (int v = t; v != s; v = p[v])\n                f = min(f, c[p[v]][v]);\n            for (int v = t; v != s; v = p[v]) {\n                c[p[v]][v] -= f;\n                c[v][p[v]] += f;\n            }\n            ans += f;\n        }\n        return ans;\n    }\n};\nint main() {\n    int n, m, s, t;\n    cin >> n >> m >> s >> t;\n    Flow f(n);\n    while (m--) {\n        int a, b;\n        long long c;\n        cin >> a >> b >> c;\n        f.add(a, b, c);\n    }\n    cout << f.run(s, t) << \"\\n\";\n}",
  "1426-4b7dd41e": "#include <iostream>\n#include <vector>\n#include <queue>\n#include <algorithm>\nusing namespace std;\nstruct Flow {\n    int n;\n    vector<vector<long long>> c;\n    Flow(int n) : n(n), c(n, vector<long long>(n)) {\n    }\n    void add(int a, int b, long long x) {\n        c[a][b] += x;\n    }\n    long long run(int s, int t) {\n        long long ans = 0;\n        while (true) {\n            vector<int> p(n, -1);\n            queue<int> q;\n            q.push(s);\n            p[s] = s;\n            while (!q.empty() && p[t] == -1) {\n                int v = q.front();\n                q.pop();\n                for (int u = 0; u < n; u++)\n                    if (p[u] == -1 && c[v][u] > 0) {\n                        p[u] = v;\n                        q.push(u);\n                    }\n            }\n            if (p[t] == -1)\n                break;\n            long long f = 4000000000000000000LL;\n            for (int v = t; v != s; v = p[v])\n                f = min(f, c[p[v]][v]);\n            for (int v = t; v != s; v = p[v]) {\n                c[p[v]][v] -= f;\n                c[v][p[v]] += f;\n            }\n            ans += f;\n        }\n        return ans;\n    }\n};\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<long long> b(n);\n    long long total = 0;\n    for (auto &x : b) {\n        cin >> x;\n        if (x > 0)\n            total += x;\n    }\n    int s = n, t = n + 1;\n    Flow f(n + 2);\n    for (int i = 0; i < n; i++)\n        if (b[i] >= 0)\n            f.add(s, i, b[i]);\n        else\n            f.add(i, t, -b[i]);\n    while (m--) {\n        int u, v;\n        cin >> u >> v;\n        f.add(u - 1, v - 1, total + 1);\n    }\n    cout << total - f.run(s, t) << \"\\n\";\n}",
  "1439-51824b51": "#include <iostream>\n#include <vector>\n#include <queue>\n#include <algorithm>\nusing namespace std;\nstruct Flow {\n    int n;\n    vector<vector<long long>> c;\n    Flow(int n) : n(n), c(n, vector<long long>(n)) {\n    }\n    void add(int a, int b, long long x) {\n        c[a][b] += x;\n    }\n    long long run(int s, int t) {\n        long long ans = 0;\n        while (true) {\n            vector<int> p(n, -1);\n            queue<int> q;\n            q.push(s);\n            p[s] = s;\n            while (!q.empty() && p[t] == -1) {\n                int v = q.front();\n                q.pop();\n                for (int u = 0; u < n; u++)\n                    if (p[u] == -1 && c[v][u] > 0) {\n                        p[u] = v;\n                        q.push(u);\n                    }\n            }\n            if (p[t] == -1)\n                break;\n            long long f = 4000000000000000000LL;\n            for (int v = t; v != s; v = p[v])\n                f = min(f, c[p[v]][v]);\n            for (int v = t; v != s; v = p[v]) {\n                c[p[v]][v] -= f;\n                c[v][p[v]] += f;\n            }\n            ans += f;\n        }\n        return ans;\n    }\n};\nint main() {\n    int n, m;\n    cin >> n >> m;\n    Flow f(n + 2);\n    vector<long long> b(n);\n    while (m--) {\n        int u, v;\n        long long l, h;\n        cin >> u >> v >> l >> h;\n        f.add(u, v, h - l);\n        b[u] -= l;\n        b[v] += l;\n    }\n    long long need = 0;\n    for (int v = 0; v < n; v++)\n        if (b[v] > 0) {\n            f.add(n, v, b[v]);\n            need += b[v];\n        } else if (b[v] < 0)\n            f.add(v, n + 1, -b[v]);\n    cout << (f.run(n, n + 1) == need ? \"SI\" : \"NO\") << \"\\n\";\n}",
