  "1795-4e47afd7": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nconst long long MOD = 998244353;\nlong long power(long long a, long long e) {\n    long long r = 1;\n    for (; e; e >>= 1, a = a * a % MOD)\n        if (e & 1)\n            r = r * a % MOD;\n    return r;\n}\nvoid transform(vector<long long> &a, bool inverse) {\n    int n = a.size();\n    for (int i = 1, j = 0; i < n; i++) {\n        int bit = n >> 1;\n        for (; j & bit; bit >>= 1)\n            j ^= bit;\n        j ^= bit;\n        if (i < j)\n            swap(a[i], a[j]);\n    }\n    for (int len = 2; len <= n; len <<= 1) {\n        long long root = power(3, (MOD - 1) / len);\n        if (inverse)\n            root = power(root, MOD - 2);\n        for (int start = 0; start < n; start += len) {\n            long long w = 1;\n            for (int j = 0; j < len / 2; j++) {\n                long long u = a[start + j], v = a[start + j + len / 2] * w % MOD;\n                a[start + j] = (u + v) % MOD;\n                a[start + j + len / 2] = (u - v + MOD) % MOD;\n                w = w * root % MOD;\n            }\n        }\n    }\n    if (inverse) {\n        long long inv = power(n, MOD - 2);\n        for (auto &x : a)\n            x = x * inv % MOD;\n    }\n}\nvector<long long> multiply(vector<long long> a, vector<long long> b) {\n    int size = a.size() + b.size() - 1, n = 1;\n    while (n < size)\n        n <<= 1;\n    a.resize(n);\n    b.resize(n);\n    transform(a, false);\n    transform(b, false);\n    for (int i = 0; i < n; i++)\n        a[i] = a[i] * b[i] % MOD;\n    transform(a, true);\n    a.resize(size);\n    return a;\n}\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<long long> a(n), b(m);\n    for (auto &x : a)\n        cin >> x;\n    for (auto &x : b)\n        cin >> x;\n    auto c = multiply(a, b);\n    for (int i = 0; i < (int)c.size(); i++) {\n        if (i)\n            cout << ' ';\n        cout << c[i];\n    }\n    cout << '\\n';\n}",
  "308-61a75ef4": "vector<long long> b(1, power(a[0], MOD - 2));\nwhile ((int)b.size() < n) {\n    int t = min(n, 2 * (int)b.size());\n    vector<long long> cut(a.begin(), a.begin() + t);\n    auto c = multiply(cut, b);\n    c.resize(t);\n    c[0] = (2 - c[0] + MOD) % MOD;\n    for (int i = 1; i < t; i++)\n        c[i] = (MOD - c[i]) % MOD;\n    b = multiply(b, c);\n    b.resize(t);\n}",
  "2045-887f6cc2": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nconst long long MOD = 998244353;\nlong long power(long long a, long long e) {\n    long long r = 1;\n    for (; e; e >>= 1, a = a * a % MOD)\n        if (e & 1)\n            r = r * a % MOD;\n    return r;\n}\nvoid transform(vector<long long> &a, bool inverse) {\n    int n = a.size();\n    for (int i = 1, j = 0; i < n; i++) {\n        int bit = n >> 1;\n        for (; j & bit; bit >>= 1)\n            j ^= bit;\n        j ^= bit;\n        if (i < j)\n            swap(a[i], a[j]);\n    }\n    for (int len = 2; len <= n; len <<= 1) {\n        long long root = power(3, (MOD - 1) / len);\n        if (inverse)\n            root = power(root, MOD - 2);\n        for (int start = 0; start < n; start += len) {\n            long long w = 1;\n            for (int j = 0; j < len / 2; j++) {\n                long long u = a[start + j], v = a[start + j + len / 2] * w % MOD;\n                a[start + j] = (u + v) % MOD;\n                a[start + j + len / 2] = (u - v + MOD) % MOD;\n                w = w * root % MOD;\n            }\n        }\n    }\n    if (inverse) {\n        long long inv = power(n, MOD - 2);\n        for (auto &x : a)\n            x = x * inv % MOD;\n    }\n}\nvector<long long> multiply(vector<long long> a, vector<long long> b) {\n    int size = a.size() + b.size() - 1, n = 1;\n    while (n < size)\n        n <<= 1;\n    a.resize(n);\n    b.resize(n);\n    transform(a, false);\n    transform(b, false);\n    for (int i = 0; i < n; i++)\n        a[i] = a[i] * b[i] % MOD;\n    transform(a, true);\n    a.resize(size);\n    return a;\n}\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a)\n        cin >> x;\n    vector<long long> b(1, power(a[0], MOD - 2));\n    while ((int)b.size() < n) {\n        int t = min(n, 2 * (int)b.size());\n        vector<long long> cut(a.begin(), a.begin() + t);\n        auto c = multiply(cut, b);\n        c.resize(t);\n        c[0] = (2 - c[0] + MOD) % MOD;\n        for (int i = 1; i < t; i++)\n            c[i] = (MOD - c[i]) % MOD;\n        b = multiply(b, c);\n        b.resize(t);\n    }\n    for (int i = 0; i < n; i++) {\n        if (i)\n            cout << ' ';\n        cout << b[i];\n    }\n    cout << '\\n';\n}",
