  "316-61935339": "vector<int> zFunction(const string &s) {\n    int n = s.size();\n    vector<int> z(n);\n    for (int i = 1, l = 0, r = 0; i < n; i++) {\n        if (i < r)\n            z[i] = min(r - i, z[i - l]);\n        while (i + z[i] < n && s[z[i]] == s[i + z[i]])\n            ++z[i];\n        if (i + z[i] > r) {\n            l = i;\n            r = i + z[i];\n        }\n    }\n    return z;\n}",
  "320-cafbee97": "for (int i = 0, l = 0, r = -1; i < n; i++) {\n    int k = i > r ? 1 : min(d1[l + r - i], r - i + 1);\n    while (i - k >= 0 && i + k < n && s[i - k] == s[i + k])\n        ++k;\n    d1[i] = k;\n    ans += k;\n    if (i + k - 1 > r) {\n        l = i - k + 1;\n        r = i + k - 1;\n    }\n}",
