  "899-7ed76f66": "#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    string s;\n    cin >> s;\n    int n = s.size();\n    vector<int> d1(n), d2(n);\n    long long ans = 0;\n    for (int i = 0, l = 0, r = -1; i < n; i++) {\n        int k = i > r ? 1 : min(d1[l + r - i], r - i + 1);\n        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k])\n            ++k;\n        d1[i] = k;\n        ans += k;\n        if (i + k - 1 > r) {\n            l = i - k + 1;\n            r = i + k - 1;\n        }\n    }\n    for (int i = 0, l = 0, r = -1; i < n; i++) {\n        int k = i > r ? 0 : min(d2[l + r - i + 1], r - i + 1);\n        while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k])\n            ++k;\n        d2[i] = k;\n        ans += k;\n        if (i + k - 1 > r) {\n            l = i - k;\n            r = i + k - 1;\n        }\n    }\n    cout << ans << '\\n';\n}",
  "543-5268f94f": "// Raíces: 0 tiene longitud -1; 1 tiene longitud 0.\n// link[0] = 0, link[1] = 0, last empieza en 1.\nint extendible(int v, int pos, const string &s) {\n    while (pos - 1 - len[v] < 0 || s[pos - 1 - len[v]] != s[pos])\n        v = link[v];\n    return v;\n}\n// Para la nueva letra c = s[pos] - 'a':\nint v = extendible(last, pos, s);\nif (next[v][c] == -1) {\n    int u = crearNodo(len[v] + 2); // Inicializa transiciones a -1.\n    next[v][c] = u;\n    link[u] = len[u] == 1 ? 1 : next[extendible(link[v], pos, s)][c];\n}\nlast = next[v][c];\nocc[last]++;",
  "401-b8536732": "while (!bfs.empty()) {\n    int v = bfs.front();\n    bfs.pop();\n    tr[v].count += tr[tr[v].link].count;\n    for (int c = 0; c < 26; c++) {\n        int u = tr[v].next[c];\n        if (u == -1)\n            tr[v].next[c] = tr[tr[v].link].next[c];\n        else {\n            tr[u].link = tr[tr[v].link].next[c];\n            bfs.push(u);\n        }\n    }\n}",
  "168-65c363c9": "string text;\ncin >> text;\nint v = 0;\nlong long answer = 0;\nfor (char ch : text) {\n    v = tr[v].next[ch - 'a'];\n    answer += tr[v].count;\n}",
  "1440-d42bfd7f": "#include <iostream>\n#include <string>\n#include <vector>\n#include <array>\n#include <queue>\nusing namespace std;\nstruct Node {\n    array<int, 26> next;\n    int link = 0;\n    long long count = 0;\n    Node() {\n        next.fill(-1);\n    }\n};\nint main() {\n    int q;\n    cin >> q;\n    vector<Node> tr(1);\n    while (q--) {\n        string p;\n        cin >> p;\n        int v = 0;\n        for (char ch : p) {\n            int c = ch - 'a';\n            if (tr[v].next[c] == -1) {\n                int id = tr.size();\n                tr[v].next[c] = id;\n                tr.emplace_back();\n            }\n            v = tr[v].next[c];\n        }\n        ++tr[v].count;\n    }\n    queue<int> bfs;\n    for (int c = 0; c < 26; c++) {\n        int u = tr[0].next[c];\n        if (u == -1)\n            tr[0].next[c] = 0;\n        else\n            bfs.push(u);\n    }\n    while (!bfs.empty()) {\n        int v = bfs.front();\n        bfs.pop();\n        tr[v].count += tr[tr[v].link].count;\n        for (int c = 0; c < 26; c++) {\n            int u = tr[v].next[c];\n            if (u == -1)\n                tr[v].next[c] = tr[tr[v].link].next[c];\n            else {\n                tr[u].link = tr[tr[v].link].next[c];\n                bfs.push(u);\n            }\n        }\n    }\n    string text;\n    cin >> text;\n    int v = 0;\n    long long answer = 0;\n    for (char ch : text) {\n        v = tr[v].next[ch - 'a'];\n        answer += tr[v].count;\n    }\n    cout << answer << '\\n';\n}",
  "503-2afb496b": "for (int k = 1; k < n; k *= 2) {\n    auto second = [&](int i) { return i + k < n ? rank[i + k] : -1; };\n    auto cmp = [&](int a, int b) {\n        return rank[a] != rank[b] ? rank[a] < rank[b] : second(a) < second(b);\n    };\n    sort(sa.begin(), sa.end(), cmp);\n    next[sa[0]] = 0;\n    for (int i = 1; i < n; i++)\n        next[sa[i]] = next[sa[i - 1]] + (cmp(sa[i - 1], sa[i]) ? 1 : 0);\n    rank = next;\n    if (rank[sa.back()] == n - 1)\n        break;\n}",
  "292-bc40919d": "int h = 0;\nfor (int i = 0; i < n; i++) {\n    if (rank[i] == 0) {\n        h = 0;\n        continue;\n    }\n    int j = sa[rank[i] - 1];\n    while (i + h < n && j + h < n && s[i + h] == s[j + h])\n        ++h;\n    ans -= h;\n    if (h)\n        --h;\n}",
  "1259-be13bdfb": "#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nint main() {\n    string s;\n    cin >> s;\n    int n = s.size();\n    vector<int> sa(n), rank(n), next(n);\n    iota(sa.begin(), sa.end(), 0);\n    for (int i = 0; i < n; i++)\n        rank[i] = (unsigned char)s[i];\n    for (int k = 1; k < n; k *= 2) {\n        auto second = [&](int i) { return i + k < n ? rank[i + k] : -1; };\n        auto cmp = [&](int a, int b) {\n            return rank[a] != rank[b] ? rank[a] < rank[b] : second(a) < second(b);\n        };\n        sort(sa.begin(), sa.end(), cmp);\n        next[sa[0]] = 0;\n        for (int i = 1; i < n; i++)\n            next[sa[i]] = next[sa[i - 1]] + (cmp(sa[i - 1], sa[i]) ? 1 : 0);\n        rank = next;\n        if (rank[sa.back()] == n - 1)\n            break;\n    }\n    for (int i = 0; i < n; i++)\n        rank[sa[i]] = i;\n    long long ans = 1LL * n * (n + 1) / 2;\n    int h = 0;\n    for (int i = 0; i < n; i++) {\n        if (rank[i] == 0) {\n            h = 0;\n            continue;\n        }\n        int j = sa[rank[i] - 1];\n        while (i + h < n && j + h < n && s[i + h] == s[j + h])\n            ++h;\n        ans -= h;\n        if (h)\n            --h;\n    }\n    cout << ans << '\\n';\n}",
